#!/usr/bin/env python3
"""Measure baked black source gutters without modifying any original image."""
from pathlib import Path
import json,re
from PIL import Image
G=Path(__file__).resolve().parents[1];rows=[]
for bank,fn,var,base,pattern in [('unbound','art.hpp','garages',0,'texture-%03d.png'),('original','original_ui.hpp','garages',1000,'original-ui-%02d.png'),('underground','content_art.hpp','undergroundGarageScenery',2000,'content-%02d.png')]:
 text=(G/'src'/fn).read_text();block=re.search(r'inline const Frame '+var+r'\[\]\s*=\s*\{(.*?)\n\};',text,re.S)[1]
 for index,line in enumerate(re.findall(r'\{([\d,]+)\}',block)[:5]):
  atlas,x,y,w,h,*_=map(int,line.split(','));file=pattern%(atlas-base);rgba=Image.open(G/'assets'/file).convert('RGBA').crop((x,y,x+w,y+h));image=Image.composite(rgba.convert('RGB'),Image.new('RGB',rgba.size),rgba.getchannel('A').point(lambda a:255 if a else 0));box=image.getbbox();assert box and (box[2]-box[0])*(box[3]-box[1])>w*h*.3
  left,top,right,bottom=box
  rows.append({'bank':bank,'index':index,'asset_file':file,'atlas':atlas,'atlas_rect':{'x':x,'y':y,'width':w,'height':h},'content_rect':{'x':left,'y':top,'width':right-left,'height':bottom-top}})
report={'method':'Bounding rectangle of visible nonblack RGB in each source garage frame. Original image files remain byte-identical. Aspect-preserving cover uses this content rectangle, not the UI gutters.','frames':rows}
(G/'menu-backdrops.json').write_text(json.dumps(report,indent=2)+'\n')
h=['// Generated by prepare_menu_backdrops.py. Source image bytes remain unchanged.','#pragma once','#include "art.hpp"','#include "menu_background.hpp"','namespace pcr {','struct MenuBackdropRegion {int atlas,x,y;BackgroundCrop content;};','inline constexpr MenuBackdropRegion MenuBackdropRegions[]={']
for r in rows:
 a=r['atlas_rect'];b=r['content_rect'];h.append('{'+','.join(map(str,[r['atlas'],a['x'],a['y']]))+',{'+','.join(map(str,[b['x'],b['y'],b['width'],b['height']]))+'}},')
h+=['};','inline BackgroundCrop menuBackdropContent(const art::Frame& f){for(const auto& r:MenuBackdropRegions)if(r.atlas==f.atlas&&r.x==f.x&&r.y==f.y)return r.content;return {0,0,double(f.w),double(f.h)};}','}'];(G/'src/menu_backdrops.hpp').write_text('\n'.join(h)+'\n');print(json.dumps({'frames':len(rows),'source_images_modified':False}))
